<!doctype html>
<html lang="{{ site.language }}" data-theme="{{ site.theme_mode }}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="{{ meta.description or site.description }}">
  <title>{{ meta.title or site.title }}</title>
  <link rel="canonical" href="{{ meta.canonical or site.url }}">
  {% if site.feed_url %}<link rel="alternate" type="application/rss+xml" title="{{ site.title }} RSS feed" href="{{ site.feed_url }}">{% endif %}
  {% if site.sitemap_url %}<link rel="sitemap" type="application/xml" title="Sitemap" href="{{ site.sitemap_url }}">{% endif %}
  <meta property="og:type" content="{{ meta.type or 'website' }}">
  <meta property="og:site_name" content="{{ site.title }}">
  <meta property="og:title" content="{{ meta.title or site.title }}">
  <meta property="og:description" content="{{ meta.description or site.description }}">
  <meta property="og:url" content="{{ meta.canonical or site.url }}">
  {% if meta.image %}<meta property="og:image" content="{{ meta.image }}">{% endif %}
  <meta name="twitter:card" content="{% if meta.image %}summary_large_image{% else %}summary{% endif %}">
  {% if site.twitter_handle %}<meta name="twitter:site" content="{{ site.twitter_handle }}">{% endif %}
  {% if meta.published %}<meta property="article:published_time" content="{{ meta.published }}">{% endif %}
  {% if meta.updated %}<meta property="article:modified_time" content="{{ meta.updated }}">{% endif %}
  <link rel="stylesheet" href="/style.css">
</head>
<body>
  <a class="skip-link" href="#content">Skip to content</a>
  <header class="site-header">
    <div class="shell header-inner">
      <a class="brand" href="/" aria-label="{{ site.title }} home">
        <span class="brand-mark" aria-hidden="true">P</span><span>{{ site.title }}</span>
      </a>
      <nav class="site-nav" aria-label="Primary navigation">
        {% for item in site.navigation %}<a href="{{ item.url }}">{{ item.label }}</a>{% endfor %}
        {% if site.feed_url %}<a href="{{ site.feed_url }}">RSS</a>{% endif %}
      </nav>
      <button class="theme-toggle" type="button" aria-label="Toggle color theme" title="Toggle color theme">◐</button>
    </div>
  </header>
  {% if preview_mode %}<aside class="preview-banner" role="status">Preview mode: draft and/or future posts may be visible in this build.</aside>{% endif %}
  <main id="content" class="shell" tabindex="-1">
    {% block content %}{% endblock %}
  </main>
  <footer class="site-footer">
    <div class="shell footer-inner">
      <p>© {{ build_time.year }} {{ site.author or site.title }}. Built with <a href="https://github.com/vincenzo-afk/Pagecraft">Pagecraft</a>.</p>
      {% if site.sitemap_url %}<a href="{{ site.sitemap_url }}">Sitemap</a>{% endif %}
    </div>
  </footer>
  <script>
    (function () {
      var key = 'pagecraft-theme'; var root = document.documentElement; var saved = localStorage.getItem(key);
      if (saved) root.dataset.theme = saved;
      document.querySelector('.theme-toggle').addEventListener('click', function () {
        var next = root.dataset.theme === 'dark' ? 'light' : 'dark'; root.dataset.theme = next; localStorage.setItem(key, next);
      });
    }());
  </script>
</body>
